  disposables.push(plateGeo);

  const topColor = color('#0b0b10');
  const bottomColor = color('#14141a');
  const grainSeed = uniform(0.015);
  const gradientNode = mix(bottomColor, topColor, uv().y);

  const plateMat = new THREE.MeshBasicNodeMaterial();
  plateMat.colorNode = gradientNode;
  disposables.push(plateMat);

  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, -0.01);
  group.add(plate);

  // Baseline grid positions (left-aligned x = -3.1)
  const LEFT_X = -3.1;
  const blocks = [];

  // Kicker
  const kickerText = ctx.fontAtlas.createText({
    text: 'NOVA ATELIER / JOURNAL',
    font: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 18,
    letterSpacing: 0.12,
    lineHeight: 1.4,
    color: '#e8ecf2',
    uppercase: true,
    maxWidth: 4.5,
    emHeight: 0.09,
  });
  kickerText.position.set(LEFT_X, 1.7, 0.01);
  group.add(kickerText);
  blocks.push(kickerText);
  disposables.push(kickerText);

  // Hero line 1: shadow + main
  const heroShadow1 = ctx.fontAtlas.createText({
    text: 'PRECISION IS',
