  });
  heroShadow1.position.set(LEFT_X + 0.02, 0.88, -0.02);
  group.add(heroShadow1);
  disposables.push(heroShadow1);

  const hero1 = ctx.fontAtlas.createText({
    text: 'PRECISION IS',
    font: 'Lora',
    fontWeight: 600,
    fontSize: 124,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    color: '#e8ecf2',
    emHeight: 0.62,
  });
  hero1.position.set(LEFT_X, 0.9, 0.02);
  group.add(hero1);
  blocks.push(hero1);
  disposables.push(hero1);

  // Hero line 2: shadow + main
  const heroShadow2 = ctx.fontAtlas.createText({
    text: 'A HABIT.',
    font: 'Lora',
    fontWeight: 600,
    fontSize: 124,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    color: '#16161d',
    emHeight: 0.62,
  });
  heroShadow2.position.set(LEFT_X + 0.02, 0.23, -0.02);
  group.add(heroShadow2);
  disposables.push(heroShadow2);

  const hero2 = ctx.fontAtlas.createText({
    text: 'A HABIT.',
    font: 'Lora',
    fontWeight: 600,
    fontSize: 124,
    letterSpacing: -0.015,
    lineHeight: 0.98,
    color: '#e8ecf2',
    emHeight: 0.62,
  });
  hero2.position.set(LEFT_X, 0.25, 0.02);
  group.add(hero2);
  blocks.push(hero2);
  disposables.push(hero2);

  // Accent underline rule
  const ruleGeo = new THREE.PlaneGeometry(2.2, 0.05);
  disposables.push(ruleGeo);
  const ruleMat = new THREE.MeshBasicNodeMaterial();
  ruleMat.colorNode = color('#ff2a38');
  ruleMat.emissiveNode = vec3(1, 0.164, 0.219).mul(1.2);
  disposables.push(ruleMat);
  const rule = new THREE.Mesh(ruleGeo, ruleMat);
  rule.position.set(LEFT_X + 1.1, -0.15, 0.02);
  rule.scale.x = 0.0001;
  group.add(rule);

  // Body paragraph
  const bodyText = ctx.fontAtlas.createText({
    text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
    font: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 26,
    letterSpacing: 0,
    lineHeight: 1.55,
    color: '#e8ecf2',
    maxWidth: 4.5,
    emHeight: 0.13,
  });
  bodyText.position.set(LEFT_X, -0.8, 0.02);
  group.add(bodyText);
  blocks.push(bodyText);
  disposables.push(bodyText);

