  const captionText = ctx.fontAtlas.createText({
    text: 'ISSUE 12 / JULY 2026',
    font: 'JetBrains Mono',
    fontWeight: 400,
    fontSize: 18,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    color: '#e8ecf2',
    emHeight: 0.09,
  });
  captionText.position.set(LEFT_X, -1.9, 0.02);
  group.add(captionText);
  blocks.push(captionText);
  disposables.push(captionText);

  // Also fade the shadow duplicates in with hero lines
  const shadowByHero = new Map([
    [hero1, heroShadow1],
    [hero2, heroShadow2],
  ]);

  // Entrance animation: rise-in per block top-to-bottom with 80ms stagger
  blocks.forEach((block, i) => {
    const startY = block.position.y + 0.4;
    const endY = block.position.y;
    block.position.y = startY;
    if (block.material) block.material.opacity = 0;
    if (block.traverse) {
      block.traverse((child) => {
        if (child.material) child.material.transparent = true;
      });
    }

    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(block.position, {
      y: endY,
      duration: 0.7,
      ease: 'power3.out',
      onUpdate: () => {
        const shadow = shadowByHero.get(block);
        if (shadow) shadow.position.y = block.position.y - 0.02;
      },
    }, 0);
    timelines.push(tl);
  });

  // Rule draw animation after hero lands (hero1 index=1 -> lands ~0.08+0.7=0.78s)
  const ruleTl = gsap.timeline({ delay: 0.86 });
  ruleTl.to(rule.scale, {
    x: 1,
    duration: 0.5,
    ease: 'power2.inOut',
    onStart: () => {
      rule.position.x = LEFT_X;
      rule.geometry.translate(0, 0, 0);
    },
  });
  // adjust rule anchor to grow from left: use pivot trick via position update
  ruleTl.eventCallback('onUpdate', () => {
    rule.position.x = LEFT_X + (2.2 * rule.scale.x) / 2;
  });
  timelines.push(ruleTl);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
    });
    group.traverse((child) => {
      if (child.geometry && typeof child.geometry.dispose === 'function') {
        child.geometry.dispose();
      }
      if (child.material && typeof child.material.dispose === 'function') {
        child.material.dispose();
      }
    });
  };

  return group;
}
